const root=resolve(import.meta.dirname,'..');
const evidence=join(root,process.env.CARGO_EVIDENCE_DIR??'evidence/alpha6');
const scratch=join(root,process.env.CARGO_SCRATCH_DIR??'.scratch/alpha6');const cli=join(root,'node_modules/semantic-release/bin/semantic-release.js');
const env0={...process.env,CI:'true',GIT_AUTHOR_NAME:'Cargo Acceptance',GIT_AUTHOR_EMAIL:'cargo@example.invalid',GIT_COMMITTER_NAME:'Cargo Acceptance',GIT_COMMITTER_EMAIL:'cargo@example.invalid',RUSTUP_TOOLCHAIN:'1.99.1'};
for(const k of Object.keys(env0))if(/TOKEN|SECRET|PASSWORD|ACTIONS_ID|GITHUB|GITLAB|^CARGO_/.test(k))delete env0[k];
const results=[];await mkdir(scratch,{recursive:true});await mkdir(evidence,{recursive:true});
async function run(cmd,args,cwd,env={}){return new Promise(res=>{let out='';const p=spawn(cmd,args,{cwd,env:{...env0,...env}});p.stdout.on('data',d=>out+=d);p.stderr.on('data',d=>out+=d);p.on('error',e=>res({code:127,out:String(e)}));p.on('close',code=>res({code,out}));});}
async function ok(cmd,args,cwd,env){const r=await run(cmd,args,cwd,env);assert.equal(r.code,0,r.out);return r.out;}
async function put(cwd,files){for(const[n,v]of Object.entries(files)){await mkdir(join(cwd,n,'..'),{recursive:true});await writeFile(join(cwd,n),v);}}
const pkg=(name,extra='')=>`[package]\nname="${name}"\nversion="1.0.0"\nedition="2021"\nlicense="MIT"\ndescription="Disposable semantic-release consumer acceptance fixture"\n${extra}`;
const core={'crates/core/Cargo.toml':pkg('fixture-core'),'crates/core/src/lib.rs':'pub fn value()->u32{42}\n#[test]fn value_test(){assert_eq!(value(),42);}\n'};
function graph(kind='runtime'){let dep='[dependencies]\nfixture-core={path="../core",version="1.0.0"}\n',src='pub fn value()->u32{fixture_core::value()}\n';let rootManifest='[workspace]\nmembers=["crates/*"]\nresolver="2"\n';if(kind==='shared'){rootManifest+='[workspace.dependencies]\nfixture-core={path="crates/core",version="1.0.0"}\n';dep='[dependencies]\nfixture-core.workspace=true\n';}if(kind==='renamed'){dep='[dependencies]\nrenamed={package="fixture-core",path="../core",version="1.0.0"}\n';src='pub fn value()->u32{renamed::value()}\n';}if(kind==='optional'){dep='[dependencies]\nfixture-core={path="../core",version="1.0.0",optional=true}\n[features]\ndefault=["dep:fixture-core"]\n';}if(kind==='target')dep='[target.\'cfg(unix)\'.dependencies]\nfixture-core={path="../core",version="1.0.0"}\n';if(kind==='build'){dep='[build-dependencies]\nfixture-core={path="../core",version="1.0.0"}\n';src='pub fn value()->u32{42}\n';}if(kind==='dev'){dep='[dev-dependencies]\nfixture-core={path="../core",version="1.0.0"}\n';src='pub fn value()->u32{42}\n#[test]fn graph_test(){assert_eq!(fixture_core::value(),42);}\n';}return {'Cargo.toml':rootManifest,...core,'crates/adapter/Cargo.toml':pkg('fixture-adapter','\n'+dep),'crates/adapter/src/lib.rs':src,...(kind==='build'?{'crates/adapter/build.rs':'fn main(){assert_eq!(fixture_core::value(),42);}\n'}:{})};}
async function config(f,extra={}){const o={synchronizeDependents:true,cargo:{registry:'fixture',trustedPublishing:false},changelog:true,...extra};await writeFile(join(f.cwd,'release.config.mjs'),`const plugin='semantic-release-workspace';\nexport default {repositoryUrl:${JSON.stringify(f.remote)},branches:['main','next',{name:'alpha',prerelease:true},{name:'preview',prerelease:'rc'}],tagFormat:'workspace-v\u0024{version}',plugins:[[plugin,${JSON.stringify(o)}]]};\n`);}
async function fixture(name,files=graph(),options={}){const d=await mkdtemp(join(scratch,name+'-'));const cwd=join(d,'work'),remote=join(d,'remote.git');await mkdir(cwd);await ok('git',['init','--bare',remote],root);await ok('git',['--git-dir',remote,'symbolic-ref','HEAD','refs/heads/main'],root);await ok('git',['init','-b','main'],cwd);const server=await startRegistry();const f={cwd,remote,d,server,env:server.env};const cargoBin=(await ok('which',['cargo'],root)).trim();const tools=join(d,'tools');await mkdir(tools);f.cargoLog=join(d,'cargo-invocations.log');f.nativeStderr=join(d,'native-stderr.log');const quote=v=>"'"+v.replaceAll("'","'\"'\"'")+"'";await writeFile(join(tools,'cargo'),`#!/bin/sh\nprintf '%s\\n' "$*" >> ${quote(f.cargoLog)}\nexec ${quote(cargoBin)} "$@" 2>> ${quote(f.nativeStderr)}\n`);await ok('chmod',['+x',join(tools,'cargo')],root);f.env.PATH=tools+':'+env0.PATH;await put(cwd,{'.gitignore':'target/\n',...files,'.cargo/config.toml':`[registries.fixture]\nindex="sparse+${server.url}/cargo/index/"\ncredential-provider="cargo:token"\n`});await config(f,options);try{await ok('cargo',['generate-lockfile'],cwd,f.env);}catch(error){await server.close();throw error;}await commit(f,'feat: establish real Cargo graph');return f;}
async function commit(f,msg){await ok('git',['add','.'],f.cwd);await ok('git',['commit','-m',msg],f.cwd);if(!(await run('git',['remote','get-url','origin'],f.cwd)).code){}else await ok('git',['remote','add','origin',f.remote],f.cwd);await ok('git',['push','-u','origin','HEAD'],f.cwd);}
async function release(f,suffix='',args=[],env={}){const before=await snapshot(f),stateBefore=f.server.state(),callBefore=(await readFile(f.cargoLog,'utf8').catch(()=>''));const r=await run(process.execPath,[cli,'--no-ci',...args],f.cwd,{...f.env,...env});if(suffix){await writeFile(join(evidence,suffix+'.log'),r.out);const state=f.server.state();await writeFile(join(evidence,suffix+'.json'),JSON.stringify({sourceBefore:before,sourceAfter:await snapshot(f),exit:r.code,args,uploadsBefore:stateBefore.uploads,uploadsAfter:state.uploads,newRequests:state.requests.slice(stateBefore.requests.length).map(x=>({method:x.method,path:x.path,authorizationPresent:!!x.authorization})),exchangeCountBefore:stateBefore.cargoExchanges?.length??0,exchangeCountAfter:state.cargoExchanges?.length??0,revocationCountBefore:stateBefore.cargoRevocations?.length??0,revocationCountAfter:state.cargoRevocations?.length??0,nativeCallsBefore:callBefore,nativeCallsAfter:await readFile(f.cargoLog,'utf8').catch(()=>''),artifacts:Object.fromEntries(Object.entries(state.cargo).map(([name,versions])=>[name,Object.fromEntries(Object.entries(versions).map(([version,x])=>[version,x.cksum]))]))},null,2));}return r;}
async function success(f,suffix,args=[],env={}){const r=await release(f,suffix,args,env);assert.equal(r.code,0,r.out);return r;}
async function snapshot(f){const paths=(await ok('git',['ls-files'],f.cwd)).trim().split('\n').filter(p=>/(?:Cargo\.(?:toml|lock)|package(?:-lock)?\.json|release.config.mjs)$/.test(p));return {head:await ok('git',['rev-parse','HEAD'],f.cwd),status:await ok('git',['status','--porcelain'],f.cwd),refs:await ok('git',['ls-remote','origin'],f.cwd),manifest:await readFile(join(f.cwd,'Cargo.toml'),'utf8'),sourceFiles:Object.fromEntries(await Promise.all(paths.map(async p=>[p,await readFile(join(f.cwd,p),'utf8')])))};}
async function withFixture(name,files,options,fn){const f=await fixture(name,files,options);try{return await fn(f);}finally{const state=f.server.state(),out=join(evidence,'cargo-artifacts',name);await mkdir(out,{recursive:true});for(const [crate,versions]of Object.entries(state.cargo))for(const [version,entry]of Object.entries(versions)){const bytes=Buffer.from(entry.artifact,'base64');assert.equal(createHash('sha256').update(bytes).digest('hex'),entry.cksum);await writeFile(join(out,crate+'-'+version+'.crate'),bytes);}await writeFile(join(out,'registry-ledger.json'),JSON.stringify({uploads:state.uploads,crates:Object.fromEntries(Object.entries(state.cargo).map(([name,versions])=>[name,Object.fromEntries(Object.entries(versions).map(([version,x])=>[version,{metadata:x.metadata,sha256:x.cksum}]))])),exchangeCount:state.cargoExchanges?.length??0,revocationCount:state.cargoRevocations?.length??0,indexDelays:state.indexDelays,requests:state.requests.map(x=>({method:x.method,path:x.path,authorizationPresent:!!x.authorization}))},null,2));try{await cp(f.nativeStderr,join(evidence,'native-'+name+'.log'));await cp(f.cargoLog,join(evidence,'native-calls-'+name+'.log'));}catch{}await f.server.close();}}
async function archivedPackage(f,name,version,label){
 const refs=(await ok('git',['--git-dir',f.remote,'for-each-ref','--format=%(refname)','refs/semantic-release-workspace/artifacts'],root)).trim().split('\n').filter(Boolean);
 const matches=[];for(const ref of refs){const metadata=JSON.parse(await ok('git',['--git-dir',f.remote,'show',ref+':metadata.json'],root));if(metadata.name===name&&metadata.vers===version)matches.push({ref,metadata});}
 assert.equal(matches.length,1,'one retained archive must match the actual adapter candidate');
 const artifact=execFileSync('git',['--git-dir',f.remote,'show',matches[0].ref+':artifact']);
 const path=join(evidence,label+'.crate');await writeFile(path,artifact);
 const manifest=await ok('tar',['-xOf',path,`${name}-${version}/Cargo.toml`],root);
 await writeFile(join(evidence,label+'-manifest.toml'),manifest);
 return {ref:matches[0].ref,metadata:matches[0].metadata,path,sha256:createHash('sha256').update(artifact).digest('hex'),normalizedManifest:manifest};
}
async function scenario(name,fn){if(process.env.CARGO_SCENARIO_FILTER&&!new RegExp(process.env.CARGO_SCENARIO_FILTER).test(name))return;let t=Date.now();try{const detail=await fn();results.push({name,status:'PASS',mode:'DOCUMENTED_PACKAGE_NAME',ms:Date.now()-t,...detail});console.log('PASS',name);}catch(e){results.push({name,status:'FAIL',mode:'DOCUMENTED_PACKAGE_NAME',ms:Date.now()-t,error:e.stack});console.log('FAIL',name,e.message.slice(-1200));}await writeFile(join(evidence,process.env.CARGO_RESULT_FILE??'lifecycle-results.json'),JSON.stringify({generatedAt:new Date().toISOString(),node:process.version,results},null,2));}
async function downstream(f,version='1.1.0'){const cwd=join(f.d,'downstream');await mkdir(cwd);await put(cwd,{'Cargo.toml':`[package]\nname="fresh-downstream"\nversion="0.1.0"\nedition="2021"\n[workspace]\n[dependencies]\nfixture-adapter={version="=${version}",registry="fixture"}\n`,'src/main.rs':'fn main(){assert_eq!(fixture_adapter::value(),42);}\n','.cargo/config.toml':await readFile(join(f.cwd,'.cargo/config.toml'),'utf8')});return await ok('cargo',['run','--quiet'],cwd,f.env);}
for(const kind of ['runtime','shared','renamed','optional','target','build','dev'])await scenario('native-publish-consume-'+kind,()=>withFixture(kind,graph(kind),{},async f=>{await ok('cargo',['test','--workspace'],f.cwd,f.env);const before=await snapshot(f);await success(f,'publish-'+kind);const state=f.server.state();assert.equal(state.uploads.length,2);assert.ok(state.uploads[0].startsWith('cargo:fixture-core@'));assert.equal(await ok('git',['rev-parse','HEAD'],f.cwd),before.head);assert.equal(await readFile(join(f.cwd,'Cargo.toml'),'utf8'),before.manifest);assert.equal(await ok('git',['status','--porcelain'],f.cwd),before.status);await downstream(f);const archive=Buffer.from(state.cargo['fixture-adapter']['1.1.0'].artifact,'base64');assert.equal(createHash('sha256').update(archive).digest('hex'),state.cargo['fixture-adapter']['1.1.0'].cksum);const cratePath=join(f.d,'adapter.crate');await writeFile(cratePath,archive);const normalized=await ok('tar',['-xOf',cratePath,'fixture-adapter-1.1.0/Cargo.toml'],root);assert.ok(!normalized.includes('../core'));assert.ok(!/workspace\s*=\s*true/.test(normalized));assert.match(normalized,/1\.1\.0/);const info=await ok('git',['show','cargo/fixture-adapter@1.1.0:crates/adapter/Cargo.toml'],f.cwd);assert.match(info,/1\.1\.0/);return {uploads:state.uploads,downstream:true,sourceRestored:true,preparedManifest:info,normalizedCrateManifest:normalized,sha256:state.cargo['fixture-adapter']['1.1.0'].cksum};}));
for(const kind of ['runtime','shared','renamed','optional','target','build','dev'])await scenario('inherited-core-publish-consume-'+kind,()=>{const files=graph(kind);files['Cargo.toml']+='[workspace.package]\nversion="1.0.0"\nedition="2021"\nlicense="MIT"\n';files['crates/core/Cargo.toml']='[package]\nname="fixture-core"\nversion.workspace=true\nedition.workspace=true\nlicense.workspace=true\ndescription="Inherited native dependency core"\n';return withFixture('inherited-'+kind,files,{},async f=>{const native=await ok('cargo',['test','--workspace','--locked'],f.cwd,f.env);await writeFile(join(evidence,'native-inherited-'+kind+'-original.log'),native);const before=await snapshot(f);await success(f,'inherited-'+kind);assert.deepEqual(await snapshot(f),{...before,refs:await ok('git',['ls-remote','origin'],f.cwd)});await downstream(f);assert.deepEqual(f.server.state().uploads,['cargo:fixture-core@1.1.0','cargo:fixture-adapter@1.1.0']);return{nativeOriginalTestExit:0,downloadedDownstreamExit:0,uploads:f.server.state().uploads,sourceRestored:true};});});
await scenario('dry-run-no-change',()=>withFixture('dry-run',graph(),{},async f=>{const before=await snapshot(f);await success(f,'dry-run', ['--dry-run']);assert.deepEqual(await snapshot(f),before);assert.equal(f.server.state().uploads.length,0);assert.equal(f.server.state().requests.filter(x=>x.method!=='GET').length,0);assert.equal(f.server.state().requests.filter(x=>/tokens|oidc/.test(x.path)).length,0);await success(f,'dry-run-first-release');const complete=await snapshot(f),count=f.server.state().uploads.length,requests=f.server.state().requests.length;await success(f,'no-change');assert.deepEqual(await snapshot(f),complete);assert.equal(f.server.state().uploads.length,count);assert.equal(f.server.state().requests.slice(requests).filter(x=>x.method!=='GET').length,0);assert.equal(f.server.state().requests.slice(requests).filter(x=>/tokens|oidc/.test(x.path)).length,0);return{zeroDryRunWrites:true,uploads:count};}));
await scenario('private-crates-no-upload-or-tag',()=>withFixture('private',{'Cargo.toml':'[workspace]\nmembers=["crates/*"]\nresolver="2"\n',...core,'crates/private/Cargo.toml':pkg('fixture-private','publish=false\n'),'crates/private/src/lib.rs':'pub fn value(){}\n','crates/private-empty/Cargo.toml':pkg('fixture-private-empty','publish=[]\n'),'crates/private-empty/src/lib.rs':'pub fn value(){}\n'}, {},async f=>{await success(f,'private');assert.equal(f.server.state().uploads.length,1);const tags=await ok('git',['tag'],f.cwd);assert.ok(!tags.includes('cargo/fixture-private'));return{uploads:f.server.state().uploads,tags};}));
