for(const control of ['reject','reject-second','once-drop'])await scenario('recovery-'+control,()=>withFixture(control,graph(),{},async f=>{f.server.control(control);const initial=await release(f,'recovery-'+control+'-first');if(control==='once-drop'&&initial.code===0){assert.equal(f.server.state().uploads.length,2);return{reconciledWithinInvocation:true,uploads:f.server.state().uploads};}assert.notEqual(initial.code,0,initial.out);const uploaded=[...f.server.state().uploads];const packed=(await readFile(f.cargoLog,'utf8')).split('\n').filter(x=>x.startsWith('package '));assert.equal(packed.length,control==='reject'?1:2);await fresh(f);f.server.control('');await success(f,'recovery-'+control+'-retry');const state=f.server.state();assert.equal(state.uploads.length,2);assert.equal(new Set(state.uploads).size,2);assert.deepEqual(state.uploads.slice(0,uploaded.length),uploaded);await downstream(f);const finalPacks=(await readFile(f.cargoLog,'utf8')).split('\n').filter(x=>x.startsWith('package '));assert.equal(finalPacks.length,2);assert.deepEqual(finalPacks.slice(0,packed.length),packed);return{retainedNativePackageCalls:packed.length,initialExit:initial.code,uploads:state.uploads,freshClone:true};}));
