await scenario('alpha-twice-main',()=>withFixture('alpha',graph(),{},async f=>{await ok('git',['checkout','-b','alpha'],f.cwd);await ok('git',['push','-u','origin','alpha'],f.cwd);await success(f,'alpha-first');await writeFile(join(f.cwd,'crates/core/src/lib.rs'),'pub fn value()->u32{42}\n// alpha second\n');await commit(f,'fix: improve core alpha');await success(f,'alpha-second');await ok('git',['checkout','main'],f.cwd);await ok('git',['merge','--no-ff','alpha','-m','feat: promote alpha graph'],f.cwd);await ok('git',['push','origin','main'],f.cwd);await success(f,'alpha-main');const state=f.server.state();assert.ok(state.uploads.includes('cargo:fixture-core@1.1.0-alpha.1'));assert.ok(state.uploads.includes('cargo:fixture-core@1.1.0-alpha.2'));assert.ok(state.uploads.includes('cargo:fixture-core@1.1.0'));await downstream(f);return{uploads:state.uploads};}));
