for(const damage of ['missing-artifact','swapped-artifact','corrupt-artifact'])await scenario('retained-state-'+damage,()=>withFixture(damage,graph(),{},async f=>{f.server.control('reject-second');const first=await release(f,'state-'+damage+'-first');assert.notEqual(first.code,0);assert.equal(f.server.state().uploads.length,1);const refs=(await ok('git',['--git-dir',f.remote,'for-each-ref','--format=%(refname)','refs/semantic-release-workspace/artifacts'],root)).trim().split('\n');assert.equal(refs.length,2);if(damage==='missing-artifact')for(const ref of refs)await ok('git',['--git-dir',f.remote,'update-ref','-d',ref],root);if(damage==='swapped-artifact'){const objects=await Promise.all(refs.map(ref=>ok('git',['--git-dir',f.remote,'rev-parse',ref],root)));await ok('git',['--git-dir',f.remote,'update-ref',refs[0],objects[1].trim()],root);await ok('git',['--git-dir',f.remote,'update-ref',refs[1],objects[0].trim()],root);}if(damage==='corrupt-artifact'){const path=join(f.d,'corrupt');await writeFile(path,'corrupt artifact bytes');const oid=(await ok('git',['--git-dir',f.remote,'hash-object','-w',path],root)).trim();for(const ref of refs)await ok('git',['--git-dir',f.remote,'update-ref',ref,oid],root);}await fresh(f);f.server.control('');const before=await snapshot(f);const retry=await release(f,'state-'+damage+'-retry');assert.notEqual(retry.code,0,retry.out);assert.equal(f.server.state().uploads.length,1);assert.equal((await snapshot(f)).head,before.head);return{retryExit:retry.code,uploads:1,damagedRemoteRefs:refs.length};}));
